HTML=Path('app/src/main/assets/prototype/index_v3.html')
s=RGA.read_text(encoding='utf-8')

# Imports/security.
for imp in ['import android.app.AlertDialog;','import android.content.SharedPreferences;','import android.text.InputType;','import android.view.View;','import android.widget.EditText;','import android.widget.LinearLayout;','import androidx.biometric.BiometricManager;','import androidx.biometric.BiometricPrompt;','import androidx.fragment.app.FragmentActivity;']:
    if imp not in s:s=s.replace('package com.rgapro1.ocaso;','package com.rgapro1.ocaso;\n'+imp,1)
s=s.replace('public class RgaProActivity extends Activity {','public class RgaProActivity extends FragmentActivity {')
old='private WebView web; private ValueCallback<Uri[]> cb; private TextRecognizer recognizer; private File cameraFile; private String cameraSide="front"; private String frontRaw="",reverseRaw="";'
new='private WebView web; private ValueCallback<Uri[]> cb; private TextRecognizer recognizer; private File cameraFile; private String cameraSide="front"; private String frontRaw="",reverseRaw=""; private String ocrMode="DNI"; private SharedPreferences securityPrefs; private boolean authenticated=false,gateShowing=false,externalDocumentActivity=false; private final java.util.concurrent.Executor biometricExecutor=java.util.concurrent.Executors.newSingleThreadExecutor();'
s=s.replace(old,new,1)

# Security-aware onCreate.
pat=r'@Override public void onCreate\(android\.os\.Bundle b\)\{.*?web\.loadUrl\("file:///android_asset/prototype/index_v3\.html"\);\}'
m=re.search(pat,s,re.S)
if m:
    s=s[:m.start()]+'''@Override public void onCreate(android.os.Bundle b){super.onCreate(b);securityPrefs=getSharedPreferences("rgapro_security",MODE_PRIVATE);android.widget.FrameLayout root=new android.widget.FrameLayout(this);web=new WebView(this);root.addView(web,new ViewGroup.LayoutParams(-1,-1));setContentView(root);WebSettings ws=web.getSettings();ws.setJavaScriptEnabled(true);ws.setDomStorageEnabled(true);ws.setAllowFileAccess(true);ws.setAllowContentAccess(true);web.setWebViewClient(new WebViewClient());web.setWebChromeClient(new WebChromeClient(){@Override public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> c,FileChooserParams p){if(cb!=null)cb.onReceiveValue(null);cb=c;pickDocument(ocrMode);return true;}});web.addJavascriptInterface(new Bridge(),"RgaProCamera");web.addJavascriptInterface(new SecurityBridge(),"RgaProSecurity");recognizer=TextRecognition.getClient(TextRecognizerOptions.DEFAULT_OPTIONS);web.setVisibility(View.INVISIBLE);web.loadUrl("file:///android_asset/prototype/index_v3.html");showSecurityGate();}'''+s[m.end():]

# Mode-aware bridge and picker.
pat=r'private class Bridge\{.*?private void startCamera\(String side\)\{'
m=re.search(pat,s,re.S)
if m:
    block='''private class Bridge{@JavascriptInterface public void capture(String side){capture(ocrMode,side);}@JavascriptInterface public void capture(String mode,String side){ocrMode=mode==null?"DNI":mode.toUpperCase(Locale.ROOT);runOnUiThread(()->startCamera(side));}@JavascriptInterface public void pickPdf(){pickDocument(ocrMode);}@JavascriptInterface public void pickPdf(String mode){ocrMode=mode==null?"DOCUMENTO":mode.toUpperCase(Locale.ROOT);pickDocument(ocrMode);}}\n    private class SecurityBridge{@JavascriptInterface public void logout(){runOnUiThread(()->lockNow());}@JavascriptInterface public void lock(){runOnUiThread(()->lockNow());}}\n    private void pickDocument(String mode){ocrMode=mode==null?"DOCUMENTO":mode.toUpperCase(Locale.ROOT);externalDocumentActivity=true;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("*/*");i.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"image/*","application/pdf"});startActivityForResult(i,PICK);}\n    private void startCamera(String side){'''
    s=s[:m.start()]+block+s[m.end():]
s=s.replace('new File(getCacheDir(),"dni")','new File(getCacheDir(),"ocr")').replace('File.createTempFile("rgapro_dni_",".jpg",dir)','File.createTempFile("rgapro_ocr_",".jpg",dir)')
s=s.replace('try{File dir=new File(getCacheDir(),"ocr");','try{externalDocumentActivity=true;File dir=new File(getCacheDir(),"ocr");',1)

# Camera/file result routing.
pat=r'@Override protected void onActivityResult\(int r,int res,Intent d\)\{.*?private void scanCamera'
m=re.search(pat,s,re.S)
if m:
    route='''@Override protected void onActivityResult(int r,int res,Intent d){super.onActivityResult(r,res,d);externalDocumentActivity=false;if(r==CAMERA){if(res==RESULT_OK&&cameraFile!=null)scanCamera(cameraFile,cameraSide);return;}if(r!=PICK)return;Uri u=res==RESULT_OK&&d!=null?d.getData():null;if(cb!=null){cb.onReceiveValue(u==null?null:new Uri[]{u});cb=null;}if(u!=null){String type=getContentResolver().getType(u);if("application/pdf".equals(type)||String.valueOf(u).toLowerCase(Locale.ROOT).contains(".pdf"))scanPdf(u,ocrMode);else scan(u,ocrMode);}}\n    private void scanCamera'''
    s=s[:m.start()]+route+s[m.end():]
s=s.replace('runBitmapOcr(b,side,encodePreview(b));','runBitmapOcr(b,ocrMode,encodePreview(b));',1).replace('private void scan(Uri u,String side){','private void scan(Uri u,String mode){',1)

# Replace native OCR parse path.
pat=r'private void runBitmapOcr\(Bitmap original,String side,String preview\)\{.*?private String findPolicyNumber'
m=re.search(pat,s,re.S)
if m:
    block='''private void runBitmapOcr(Bitmap original,String mode,String preview){if(original==null){err();return;}Bitmap n=normalize(original,2600),e=enhance(n);recognizer.process(InputImage.fromBitmap(n,0)).addOnSuccessListener(a->recognizer.process(InputImage.fromBitmap(e,0)).addOnSuccessListener(b->{deliver(choose(a==null?"":a.getText(),b==null?"":b.getText()),mode,preview);release(n,e,original);}).addOnFailureListener(x->{deliver(a==null?"":a.getText(),mode,preview);release(n,e,original);})).addOnFailureListener(x->recognizer.process(InputImage.fromBitmap(e,0)).addOnSuccessListener(t->{deliver(t==null?"":t.getText(),mode,preview);release(n,e,original);}).addOnFailureListener(y->{release(n,e,original);err();}));}\n    private String choose(String a,String b){if(!"DNI".equalsIgnoreCase(ocrMode))return(a+"\\n"+b).trim();DniOcrParser.Result x=DniOcrParser.parse(a),y=DniOcrParser.parse(b);int sx=x.confidence+(x.surname.isEmpty()?0:10)+(x.birthDate.isEmpty()?0:10)+(x.dni.isEmpty()?0:10),sy=y.confidence+(y.surname.isEmpty()?0:10)+(y.birthDate.isEmpty()?0:10)+(y.dni.isEmpty()?0:10);return sx>=sy?a+"\\n"+b:b+"\\n"+a;}\n    private void deliver(String raw,String mode,String preview){try{ocrMode=mode==null?"DOCUMENTO":mode.toUpperCase(Locale.ROOT);JSONObject o=parseForMode(raw,ocrMode);o.put("mode",ocrMode);o.put("preview",preview==null?"":preview);o.put("sourceData",preview==null||preview.isEmpty()?"":"data:image/jpeg;base64,"+preview);o.put("sourceName","captura_"+ocrMode.toLowerCase(Locale.ROOT)+".jpg");o.put("sourceType","image/jpeg");web.evaluateJavascript("window.setOcrResult("+JSONObject.quote(o.toString())+");",null);Toast.makeText(this,"DNI".equals(ocrMode)?"DNI/NIE leído: revisa los campos":"POLIZA".equals(ocrMode)?"Póliza leída: revisa los campos":"Documento leído: revisa el texto",Toast.LENGTH_LONG).show();}catch(Exception e){err();}}\n    private void scanPdf(Uri u,String mode){ocrMode=mode==null?"DOCUMENTO":mode.toUpperCase(Locale.ROOT);PdfOcrHelper.process(this,u,new PdfOcrHelper.Callback(){public void onSuccess(String text){runOnUiThread(()->{try{JSONObject o=parseForMode(text,ocrMode);o.put("mode",ocrMode);o.put("preview","");o.put("sourceName","documento_"+ocrMode.toLowerCase(Locale.ROOT)+".pdf");o.put("sourceType","application/pdf");web.evaluateJavascript("window.setOcrResult("+JSONObject.quote(o.toString())+");",null);Toast.makeText(RgaProActivity.this,"PDF completo procesado. Revisa los datos.",Toast.LENGTH_LONG).show();}catch(Exception e){err();}});}public void onError(Exception e){runOnUiThread(()->Toast.makeText(RgaProActivity.this,"No se pudo leer el PDF: "+e.getMessage(),Toast.LENGTH_LONG).show());}});}\n    private JSONObject parseForMode(String raw,String mode)throws Exception{String m=mode==null?"DOCUMENTO":mode.toUpperCase(Locale.ROOT);if("DNI".equals(m)){DniOcrParser.Result r=DniOcrParser.parse(raw);JSONObject o=new JSONObject();o.put("documentNumber",r.dni);o.put("birthDate",r.birthDate);o.put("name",r.name);o.put("surname",r.surname);o.put("confidence",r.confidence);o.put("raw",raw==null?"":raw);return o;}if("POLIZA".equals(m))return PolicyOcrParser.parse(raw);JSONObject o=new JSONObject();o.put("confidence",0);o.put("raw",raw==null?"":raw);o.put("policyType","");o.put("documentNumber","");o.put("name","");o.put("surname","");o.put("birthDate","");return o;}\n    private String findPolicyNumber'''
    s=s[:m.start()]+block+s[m.end():]

# Security gate, password + biometrics, relock on returning from background. External camera/file picker is exempt.
if 'private void showSecurityGate()' not in s:
    security='''private void showSecurityGate(){if(gateShowing)return;gateShowing=true;web.setVisibility(View.INVISIBLE);if(securityPrefs.getString("pin","").isEmpty()){showCreatePin();}else showLoginGate();}\n    private EditText pinEdit(String h){EditText e=new EditText(this);e.setHint(h);e.setSingleLine(true);e.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_VARIATION_PASSWORD);return e;}\n    private void showCreatePin(){LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(30,8,30,8);EditText a=pinEdit("Clave de 6 dígitos"),b=pinEdit("Repite la clave");box.addView(a);box.addView(b);new AlertDialog.Builder(this).setTitle("Configurar acceso RgaPro").setMessage("Protege la aplicación con una clave y biometría si está disponible.").setView(box).setCancelable(false).setPositiveButton("Guardar",(d,w)->{String p=a.getText().toString();if(!p.matches("\\\\d{6}")||!p.equals(b.getText().toString())){Toast.makeText(this,"La clave debe tener 6 dígitos y coincidir.",Toast.LENGTH_LONG).show();gateShowing=false;showSecurityGate();return;}securityPrefs.edit().putString("pin",p).putBoolean("biometric",true).apply();authenticated=true;gateShowing=false;web.setVisibility(View.VISIBLE);}).show();}\n    private void showLoginGate(){EditText e=pinEdit("Clave de 6 dígitos");AlertDialog d=new AlertDialog.Builder(this).setTitle("RgaPro · Acceso seguro").setMessage("Usa tu clave o la biometría del dispositivo.").setView(e).setCancelable(false).setNegativeButton("Biometría",null).setPositiveButton("Entrar",null).create();d.setOnShowListener(x->{d.getButton(-1).setOnClickListener(v->{if(securityPrefs.getString("pin","").equals(e.getText().toString())){d.dismiss();authenticated=true;gateShowing=false;web.setVisibility(View.VISIBLE);}else e.setError("Clave incorrecta");});d.getButton(-2).setOnClickListener(v->{d.dismiss();authenticateBiometric();});});d.show();}\n    private void authenticateBiometric(){int can=BiometricManager.from(this).canAuthenticate(BiometricManager.Authenticators.BIOMETRIC_WEAK);if(can!=BiometricManager.BIOMETRIC_SUCCESS){Toast.makeText(this,"Biometría no disponible. Usa la clave.",Toast.LENGTH_LONG).show();showLoginGate();return;}BiometricPrompt bp=new BiometricPrompt(this,biometricExecutor,new BiometricPrompt.AuthenticationCallback(){@Override public void onAuthenticationSucceeded(BiometricPrompt.AuthenticationResult r){runOnUiThread(()->{authenticated=true;gateShowing=false;web.setVisibility(View.VISIBLE);});}@Override public void onAuthenticationError(int c,CharSequence m){runOnUiThread(()->showLoginGate());}});bp.authenticate(new BiometricPrompt.PromptInfo.Builder().setTitle("RgaPro").setSubtitle("Acceso biométrico").setNegativeButtonText("Usar clave").setAllowedAuthenticators(BiometricManager.Authenticators.BIOMETRIC_WEAK).build());}\n    private void lockNow(){authenticated=false;gateShowing=false;showSecurityGate();}\n    @Override protected void onStop(){super.onStop();if(authenticated&&!isChangingConfigurations()&&!externalDocumentActivity){authenticated=false;gateShowing=false;if(web!=null)web.setVisibility(View.INVISIBLE);}}\n    @Override protected void onResume(){super.onResume();if(!authenticated&&web!=null&&!gateShowing)showSecurityGate();}\n'''
    s=s.replace('    @Override protected void onDestroy()',security+'    @Override protected void onDestroy()',1)
RGA.write_text(encoding='utf-8') if False else RGA.write_text(s,encoding='utf-8')

h=HTML.read_text(encoding='utf-8')
if 'n-logout' not in h:
    h=h.replace('<button id="n-alarms" onclick="show(\'alarms\')">Alarmas</button>','<button id="n-alarms" onclick="show(\'alarms\')">Alarmas</button><button id="n-logout" onclick="logout()">Cerrar sesión</button>',1)
pat=r'function setOcrType\(t\)\{.*?\}function takeFront\(\)'
rep="""function setOcrType(t){ocrType=t;ocrData=emptyOcr();ocrEditing=false;document.getElementById('ocrTypeDni').className=t==='DNI'?'primary':'secondary';document.getElementById('ocrTypeDoc').className=t==='DOCUMENTO'?'primary':'secondary';document.getElementById('ocrTypePol').className=t==='POLIZA'?'primary':'secondary';let rev=document.querySelector('button[onclick=\"takeReverse()\"]'),front=document.querySelector('button[onclick=\"takeFront()\"]');if(rev)rev.style.display=t==='DNI'?'':'none';if(front)front.textContent=t==='DNI'?'📷 Tomar anverso':t==='POLIZA'?'📷 Fotografiar póliza':'📷 Fotografiar documento';document.getElementById('step').textContent=t==='DNI'?'DNI/NIE: leer ANVERSO y después REVERSO. La fecha de caducidad no se guarda.':t==='POLIZA'?'PÓLIZA: solo campos de póliza. El OCR del DNI queda oculto. JPG y PDF se leen como póliza cuando estás en este modo.':'DOCUMENTO JPG/PDF: OCR general del documento, sin campos de DNI ni póliza hasta que se clasifique.';renderOcrFields()}
function takeFront()"""
h=re.sub(pat,rep,h,count=1,flags=re.S)
h=h.replace("function takeFront(){if(window.RgaProCamera)RgaProCamera.capture('front');else alert('Cámara nativa no disponible')}","function takeFront(){if(window.RgaProCamera)RgaProCamera.capture(ocrType,'front');else alert('Cámara nativa no disponible')}")
h=h.replace("function takeReverse(){if(window.RgaProCamera)RgaProCamera.capture('reverse');else alert('Cámara nativa no disponible')}","function takeReverse(){if(window.RgaProCamera&&ocrType==='DNI')RgaProCamera.capture('DNI','reverse');else if(ocrType!=='DNI')alert('El reverso solo corresponde al OCR de DNI/NIE')}")
h=h.replace("function openFile(){if(window.RgaProCamera)RgaProCamera.pickPdf();else document.getElementById('file').click()}","function openFile(){if(window.RgaProCamera)RgaProCamera.pickPdf(ocrType);else document.getElementById('file').click()}")
h=h.replace("ocrData={...ocrData,...x};if(x.preview)","if(x.mode)ocrType=x.mode;ocrData={...emptyOcr(),...ocrData,...x};if(x.preview)")
h=h.replace("let hc=ocrData.documentNumber?state.clients.find(c=>norm(c.dni)===norm(ocrData.documentNumber)):null;if(!hc&&holder)","let hc=null;if(holder)")
if 'function logout()' not in h:h=h.replace('function show(id){','function logout(){if(window.RgaProSecurity)RgaProSecurity.logout();else{try{location.reload()}catch(e){}}}\nfunction show(id){',1)
h=h.replace('border-bottom:1px solid #000','border-bottom:0').replace('background:#000','background:var(--bg)').replace('background-color:#000','background-color:var(--bg)')
